import json
Q=[]
def mc(q,opts,ok,explain,why=None,data=None):
    Q.append({'type':'mc','q':q,'opts':opts,'ok':ok,'explain':explain,'why':{str(k):v for k,v in (why or {}).items()},'data':data})
mc("Tienes los datos en A2:A31. ¿Qué fórmula da la media?",["=PROMEDIO(A2:A31)","=MEDIA(A2:A31)","=SUMA(A2:A31)","=PROMEDIO(A2;A31)"],0,"PROMEDIO con el rango escrito con dos puntos (:).",{3:"Con punto y coma (;) solo coges A2 y A31, no todo el rango. El rango se escribe con dos puntos."})
mc("¿Qué función da la varianza S² de los apuntes (la que divide entre n)?",["VAR.P","VAR.S","DESVEST.P","COVARIANZA.P"],0,".P = población, divide entre n. Es la S² de clase.",{1:"VAR.S divide entre n − 1: es la cuasivarianza s².",2:"DESVEST.P es la desviación típica (la raíz de la varianza)."})
mc("¿Y la cuasidesviación típica s (divide entre n − 1)?",["DESVEST.S","DESVEST.P","VAR.S","RAIZ"],0,"DESVEST.S: desviación típica de la muestra (Sample), entre n − 1.")
mc("¿Qué devuelve =CONTAR.SI(A2:A31;3)?",["Cuántas celdas valen 3","La suma de los 3 primeros datos","El tercer dato","Cuántos datos hay en total"],0,"CONTAR.SI cuenta cuántas celdas cumplen la condición: aquí, valer 3. Es la nᵢ del valor 3.")
mc("En E2 tienes =CONTAR.SI(A2:A31;D2) y la arrastras hacia abajo. ¿Qué pasa?",["El rango se mueve a A3:A32, A4:A33… y los conteos salen mal","Todo sale bien","Excel da error #¡VALOR!","Solo cambia D2"],0,"Sin $, al arrastrar se mueve todo. Hay que fijar el rango: $A$2:$A$31.")
mc("¿Para qué sirve el $ en $A$2?",["Para que la celda no cambie al arrastrar la fórmula","Para que el número salga en euros","Para multiplicar","Para sumar la columna"],0,"$ fija la columna y la fila: al copiar la fórmula, sigue apuntando a A2.")
mc("En =B2/$B$8, ¿qué representa $B$8 en una tabla de frecuencias?",["El total n, que tiene que ser el mismo en todas las filas","La frecuencia de la fila 8","La media","El valor más alto"],0,"Para fᵢ = nᵢ ÷ n, el denominador siempre es n: por eso se fija.")
mc("¿Qué calcula =SUMAPRODUCTO(A2:A6;B2:B6)/SUMA(B2:B6) si A son valores y B frecuencias?",["La media de la tabla de frecuencias","La varianza","La suma de los valores","La mediana"],0,"SUMAPRODUCTO hace Σxᵢ·nᵢ y SUMA da n: Σxᵢnᵢ ÷ n = x̄.")
mc("=CUARTIL.INC(A2:A31;3) devuelve…",["El tercer cuartil C₃","El tercer dato","El percentil 3","El 3 % de los datos"],0,"El segundo número indica qué cuartil: 1, 2 (mediana) o 3.")
mc("¿Cómo pides el percentil 90 de A2:A31?",["=PERCENTIL.INC(A2:A31;0,9)","=PERCENTIL.INC(A2:A31;90)","=CUARTIL.INC(A2:A31;90)","=PERCENTIL(90)"],0,"El porcentaje va en tanto por uno: 0,9.",{1:"Excel quiere el percentil en tanto por uno (entre 0 y 1). 90 da error."})
mc("Excel da C₃ = 2,25 y con la receta de los apuntes te sale 2,5. ¿Qué pasa?",["Los dos están bien: Excel usa otro método para los cuartiles","Excel está mal","Te has equivocado seguro","Hay que usar la media"],0,"CUARTIL.INC interpola; la receta de los apuntes no. En papel usa la receta y, si te dan una salida de ordenador, sus números.")
mc("¿Qué función da la moda de unos datos sueltos?",["MODA.UNO","MEDIANA","MAX","CONTAR.SI"],0,"MODA.UNO devuelve el valor que más se repite.")
mc("Con datos en intervalos, ¿Excel calcula la mediana con =MEDIANA de la tabla?",["No: con la tabla agrupada hay que escribir la fórmula de los apuntes con celdas","Sí, siempre","Sí, con =MEDIANA.INTERVALO","Solo si los intervalos son iguales"],0,"MEDIANA solo sirve con los datos sueltos. Con intervalos se escribe Lᵢ₋₁ + (n/2 − Nᵢ₋₁)/nᵢ · aᵢ con referencias a celdas.")
mc("¿Qué hace =FRECUENCIA(A2:A81;C2:C5)?",["Cuenta cuántos datos caen en cada intervalo, usando los extremos superiores de C2:C5","Calcula la frecuencia relativa","Calcula la moda","Ordena los datos"],0,"Cuenta los datos ≤ cada extremo y > el anterior: intervalos (a, b].")
mc("¿Con qué herramienta de Excel se construye una tabla de doble entrada a partir de los datos?",["Tabla dinámica","Formato condicional","Gráfico de dispersión","Ordenar y filtrar"],0,"Insertar → Tabla dinámica: una variable en Filas, otra en Columnas y una de ellas en Valores (cuenta).")
mc("En la tabla dinámica, ¿cómo ves los porcentajes de cada fila (Y | X)?",["Mostrar valores como → % del total de filas","Mostrar valores como → % del total general","Formato de celdas → Porcentaje","Insertar → Gráfico"],0,"% del total de filas: cada fila suma 100 %. Son las condicionadas Y | X.")
mc("Para la tabla «si fueran independientes» escribes =$E3*B$6 y arrastras. ¿Por qué los $ a medias?",["Para que cada casilla use el total de su fila (columna E) y el de su columna (fila 6)","Por estética","Para que dé error si no son independientes","Es igual que sin $"],0,"$E fija la columna de totales de fila; $6 fija la fila de totales de columna.")
mc("¿Qué función da la covarianza S_XY de clase (divide entre n)?",["COVARIANZA.P","COVARIANZA.M","COEF.DE.CORREL","VAR.P"],0,".P divide entre n, como en los apuntes.")
mc("X en A2:A11 e Y en B2:B11. ¿Cuál da la pendiente de la recta de Y sobre X?",["=PENDIENTE(B2:B11;A2:A11)","=PENDIENTE(A2:A11;B2:B11)","=INTERSECCION.EJE(B2:B11;A2:A11)","=COEF.DE.CORREL(A2:A11;B2:B11)"],0,"Primero la Y y después la X.",{1:"Al revés te da la pendiente de la recta de X sobre Y.",2:"Esa da el término independiente a."})
mc("¿Qué devuelve =INTERSECCION.EJE(B2:B11;A2:A11)?",["El término independiente a de la recta","La pendiente b","El valor de r","El punto de medias"],0,"Es el valor de Y cuando X = 0: el término a.")
mc("¿Qué fórmula predice Y cuando X = 11?",["=PRONOSTICO.LINEAL(11;B2:B11;A2:A11)","=PRONOSTICO.LINEAL(B2:B11;A2:A11;11)","=PENDIENTE(11)","=PROMEDIO(B2:B11)*11"],0,"Orden: el valor de X, luego los Y, luego los X.")
mc("¿Qué función da R² directamente?",["COEFICIENTE.R2","COEF.DE.CORREL","PENDIENTE","VAR.P"],0,"COEFICIENTE.R2(Y;X). También puedes elevar COEF.DE.CORREL al cuadrado.")
mc("En un gráfico de dispersión, ¿cómo sacas la recta y el R²?",["Clic derecho en un punto → Agregar línea de tendencia → Lineal, y marcar «Presentar ecuación» y «R cuadrado»","Insertar → Recta","Formato de celdas","Datos → Ordenar"],0,"La línea de tendencia escribe la ecuación y el R² encima del gráfico.")
mc("Tienes los salarios en B2:B12 y el año base en la fila 2. ¿Qué escribes en C2 para el índice, antes de arrastrar?",["=B2/$B$2*100","=B2/B2*100","=$B2/B2*100","=B2*100"],0,"El año base se fija con $B$2 para que todas las filas dividan entre él.",{1:"Sin $, al arrastrar cada año se dividiría entre sí mismo: todo saldría 100."})
mc("¿Qué calcula =B3/B2-1 con formato %?",["La tasa de variación entre B2 y B3","El índice","La media","La diferencia en euros"],0,"V₁/V₀ − 1 = tasa de variación.")
mc("¿Cómo escribes en Excel la tasa mensual equivalente a un 6 % anual?",["=1,06^(1/12)-1","=1,06^1/12-1","=6/12","=RAIZ(1,06)/12"],0,"La raíz duodécima es elevar a (1/12), con el paréntesis.",{1:"Sin paréntesis, Excel hace 1,06¹ y luego divide entre 12."})
mc("¿Qué función da la media geométrica de A1:A3?",["MEDIA.GEOM","PROMEDIO","PRODUCTO","RAIZ"],0,"MEDIA.GEOM multiplica y hace la raíz n-ésima. También =PRODUCTO(A1:A3)^(1/3).")
mc("p₀ en B, q₀ en C y pₜ en D. ¿Qué fórmula es el índice de Laspeyres de precios?",["=SUMAPRODUCTO(D2:D6;C2:C6)/SUMAPRODUCTO(B2:B6;C2:C6)*100","=SUMAPRODUCTO(D2:D6;B2:B6)/SUMA(C2:C6)*100","=SUMA(D2:D6)/SUMA(B2:B6)*100","=PROMEDIO(D2:D6)/PROMEDIO(B2:B6)*100"],0,"Σpₜq₀ / Σp₀q₀ × 100: la misma cantidad (q₀) arriba y abajo.")
mc("Salario en B2 e IPC en C2 (base 100). ¿Qué fórmula da el salario real?",["=B2/C2*100","=B2*C2/100","=B2-C2","=C2/B2*100"],0,"Deflactar es dividir entre el IPC (y × 100 si el IPC está en base 100).")
mc("Excel muestra #¡DIV/0! en una celda. ¿Qué significa?",["Que estás dividiendo entre una celda vacía o que vale 0","Que el número es demasiado grande","Que falta un paréntesis","Que la función no existe"],0,"Suele pasar al arrastrar sin $: el denominador se mueve a una celda vacía.")
assert len(Q)==30,len(Q)
import random
rng=random.Random(7)
for q in Q:
    idx=list(range(len(q['opts'])));rng.shuffle(idx)
    q['opts']=[q['opts'][i] for i in idx]
    q['ok']=idx.index(q['ok'])
    q['why']={str(idx.index(int(k))):v for k,v in q['why'].items()}
json.dump({'preguntas-de-excel-sin-ordenador':Q},open('/home/claude/xl3/checks_papel.json','w'),ensure_ascii=False,indent=1)
print(len(Q))
